WITH other_users_with_matching_permissions AS (
SELECT up.key_asset_report_id
FROM key_asset_report_org up where  up.org_id in

        #{item}

GROUP BY up.key_asset_report_id
HAVING
(select  count(*) from   key_asset_report_org where key_asset_report_id  =up.key_asset_report_id )  <=  count(*)
)
SELECT u.*
FROM key_asset_report u
JOIN other_users_with_matching_permissions oump ON u.id = oump.key_asset_report_id
WHERE
 u.tenant_uid = #{tenantUid}

    AND u.report_year =#{reportYear}


    AND u.report_type =#{reportType}


    AND u.asset_name like  concat('%',#{assetName},'%')



    AND u.asset_dept_name  like  concat('%',#{assetDeptName},'%')


    AND u.form_filler like   concat('%',#{formFiller},'%')

order by  u.create_time desc
LIMIT #{page} OFFSET #{offset}

